export class LivingLoop {
  constructor({unit,intervalMs=5000}={}){if(!unit)throw new Error('unit required');this.unit=unit;this.metabolism=unit.metabolism;this.fabric=unit.fabric;this.coordinator=unit.coordinator;this.needs=new NeedField();this.variation=new TraceableVariation({fabric:this.fabric,coordinator:this.coordinator,metabolism:this.metabolism});this.rules=unit.rules;this.intervalMs=intervalMs;this.timer=null;this.pulses=0;this.events=[];this.growths=[];this.lastPulseAt=null;this.lastCollective=null;}
  start(){if(this.timer)return false;this.lastPulseAt=Date.now();this.timer=setInterval(()=>this.pulse().catch(e=>this.events.push({type:'pulse-error',error:String(e),at:Date.now()})),this.intervalMs);if(typeof this.timer?.unref==='function')this.timer.unref();this.events.push({type:'life-started',at:Date.now()});return true;}
  stop(){if(!this.timer)return false;clearInterval(this.timer);this.timer=null;this.events.push({type:'life-stopped',at:Date.now()});return true;}
  observeCollective(event,input={}){this.lastCollective={event:clone(event),input:this.#safeInput(input),at:Date.now()};const failures=event.outputs?.filter(x=>!x.ok)||[];const elapsed=event.durationMs||0;this.metabolism.registerWork({cost:.0015+Math.min(.008,elapsed/250000),kind:event.type,evidence:{collectiveId:event.id},failed:failures.length>0});if(failures.length)this.needs.observe({kind:'repair',subject:event.id,pressure:.16,reason:'specialist failure in collective path',evidence:failures.map(x=>({type:'failure',organ:x.organ,error:x.out?.error||null})),context:{route:event.route}});return this.lastCollective;}
  observeUnresolved({kind='unresolved',subject='runtime',pressure=.08,reason='unresolved state',evidence=[],context=null}={}){return this.needs.observe({kind,subject,pressure,reason,evidence,context});}
  observeCapabilityGap({capabilities=[],subject='runtime',pressure=.12,reason='required capability is absent',evidence=[],dimension=5}={}){const caps=[...new Set(capabilities.map(String).filter(Boolean))];if(!caps.length)throw new Error('capability gap requires at least one capability');return this.needs.observe({kind:'capability-gap',subject,pressure,reason,evidence,context:{capabilities:caps,dimension}});}
  async pulse({dtMs=null}={}){const now=Date.now();if(dtMs==null)dtMs=this.lastPulseAt?Math.max(1,now-this.lastPulseAt):this.intervalMs;this.lastPulseAt=now;this.pulses++;this.needs.decay();const fabric=this.fabric.status(),mem=this.unit.memory.snapshot?.()||{};this.metabolism.tick({dtMs,activeProcesses:fabric.liveProcessWorkers||0,memoryLoad:Object.values(mem).reduce((n,v)=>n+(Array.isArray(v)?v.length:0),0),unresolvedNeeds:this.needs.open().length});this.#deriveNeeds(fabric);const development=this.unit.development?.resolve({reason:'life-pulse'})||null;this.#deriveDevelopmentNeed(development);const coupled=this.unit.coupledDevelopment?.resolve?.({reason:'life-pulse',synthiaState:development})||null;if(coupled?.supportGap?.length)this.observeCapabilityGap({capabilities:coupled.supportGap,subject:coupled.id,pressure:Math.min(.22,.08+coupled.user.distance*.14),reason:coupled.statement,evidence:[{type:'coupled-development',id:coupled.id,cycleId:coupled.evidence?.cycleId}],dimension:5});const emergence=this.unit.emergence?.onPulse?.(development)||null;const action=await this.#respondToPressure();const event={type:'life-pulse',pulse:this.pulses,dtMs,vitality:this.metabolism.vitality,adaptationBudget:this.metabolism.adaptationBudget,repairPressure:this.metabolism.repairPressure,openNeeds:this.needs.open().length,development:development?{id:development.id,distance:development.distance,status:development.becoming.status,next:development.becoming.nearestNextState}:null,coupled:coupled?{id:coupled.id,userDistance:coupled.user.distance,synthiaDistance:coupled.synthia.distance,supportGap:coupled.supportGap}:null,emergence:emergence?{hypothesisId:emergence.hypothesis?.id||null,taskStatus:emergence.task?.status||null,metaLearning:emergence.metaLearning||null}:null,action,at:now};event.organism= this.unit.autonomousOrganism?.pulse?.({lifeEvent:event})||null;this.events.push(event);return event;}
  #deriveNeeds(fabric){if(this.metabolism.vitality<.48)this.needs.observe({kind:'replenishment',subject:'organism',pressure:(.48-this.metabolism.vitality)*.18+.01,reason:'maintenance expenditure has lowered vitality',evidence:[{type:'metabolic-state',vitality:this.metabolism.vitality}]});if(this.metabolism.repairPressure>.08)this.needs.observe({kind:'repair',subject:'organism',pressure:this.metabolism.repairPressure*.12,reason:'accumulated contradictory/failure evidence',evidence:[{type:'repair-pressure',value:this.metabolism.repairPressure}]});if(this.metabolism.repairPressure>.15&&!this.#hasCapability('organism:repair-support'))this.needs.observe({kind:'capability-gap',subject:'organism:repair-support',pressure:Math.min(.28,.12+this.metabolism.repairPressure*.35),reason:'repair pressure exceeds the capability of the current active anatomy',evidence:[{type:'repair-pressure',value:this.metabolism.repairPressure},{type:'tool-count',value:this.unit.runtime.getRegisteredTools().length}],context:{capabilities:['organism:repair-support'],dimension:5}});for(const h of fabric.hypotheses||[]){if(h.status!=='supported'&&h.confidence>.35)this.needs.observe({kind:'resolve-hypothesis',subject:h.id,pressure:Math.min(.12,h.confidence*.08),reason:'relationship has evidence but is not structurally resolved',evidence:[{type:'relation-hypothesis',id:h.id,confidence:h.confidence}],context:{members:h.members}});}}

  #deriveDevelopmentNeed(development){
    if(!development)return;
    const missing=development.becoming?.missingCapabilities||[];
    if(missing.length){this.needs.observe({kind:'development',subject:development.id,pressure:Math.min(.22,.08+development.distance*.18),reason:development.becoming.statement,evidence:[{type:'developmental-attractor',id:development.id,distance:development.distance}],context:{capabilities:missing,developmentId:development.id}});}
  }
  async #respondToPressure(){const need=this.needs.open().find(n=>n.actionable);if(!need)return null;if(need.kind==='replenishment')return {needId:need.id,action:'conserve-and-await-verified-success',selfOriginated:true};if(need.kind==='resolve-hypothesis'){const h=this.fabric.inspect(need.subject);if(h?.status==='supported'){this.needs.satisfy(need.id,{evidence:{type:'fabric-support',id:h.id}});return {needId:need.id,action:'recognized-supported-relation',selfOriginated:true};}return {needId:need.id,action:'continue-observation',selfOriginated:true};}if(need.kind==='development'){const caps=need.context?.capabilities||[];if(caps.length&&this.metabolism.adaptationBudget>=.25){const promoted={...need,kind:'capability-gap',context:{...need.context,capabilities:caps}};return this.#growForNeed(promoted);}return {needId:need.id,action:'hold-developmental-attractor-until-capacity-or-evidence-changes',developmentId:need.subject,selfOriginated:true};}
    if(need.kind==='capability-gap'&&this.metabolism.adaptationBudget>=.25)return this.#growForNeed(need);if(need.kind==='repair'&&this.metabolism.adaptationBudget>=.25){const parent=this.#adaptableParent();if(parent){const spent=this.metabolism.consumeAdaptation(.25,{reason:'test traceable structural variation',evidence:{needId:need.id,parentId:parent.id}});if(spent.spent>0){const candidate=this.variation.candidate(parent,{reason:need.reason});if(candidate){const result=await this.#testCandidate(candidate);this.needs.attempt(need.id,{kind:'structural-variation',candidateId:candidate.id,ok:result?.better===true,result});if(result?.better){this.variation.retain(candidate.id,{score:result.score,evidence:{type:'bounded-replay',...result}});this.metabolism.relieveRepairPressure(.12,{reason:'retained lower-cost/healthier structure'});this.needs.satisfy(need.id,{evidence:{type:'variation-retained',variantId:candidate.id},result});}else this.variation.reject(candidate.id,{evidence:{type:'bounded-replay',...result}});return {needId:need.id,action:'tested-structural-variation',candidateId:candidate.id,result,selfOriginated:true};}}}const support=await this.#useCapability('organism:repair-support',need);if(support)return support;return {needId:need.id,action:'repair-pressure-held-insufficient-safe-evidence',selfOriginated:true};}return {needId:need.id,action:'observe',selfOriginated:true};}
  #hasCapability(capability){return this.unit.runtime.getRegisteredTools().some(t=>t.provides?.includes(capability));}
  async #growForNeed(need){const capabilities=[...new Set(need.context?.capabilities||[need.subject])].filter(Boolean);if(!capabilities.length)return {needId:need.id,action:'growth-blocked-no-capability',selfOriginated:true};if(capabilities.every(c=>this.#hasCapability(c))){this.needs.satisfy(need.id,{evidence:{type:'capability-already-present',capabilities}});return {needId:need.id,action:'recognized-existing-capability',capabilities,selfOriginated:true};}const context=this.#growthContext(need,capabilities);const resolution=this.rules.evaluateGrowth({need,capabilities,context});context.expression.parameters.fiveDimensionalRuleHash=resolution.ruleHash;context.expression.parameters.fiveDimensionalResolution=resolution;if(!resolution.permit){this.needs.attempt(need.id,{kind:'five-dimensional-rule-gate',ok:false,result:resolution});return {needId:need.id,action:'growth-held-by-five-dimensional-rules',capabilities,resolution,selfOriginated:true};}const spent=this.metabolism.consumeAdaptation(.25,{reason:'five-dimensionally authorized bounded growth',evidence:{needId:need.id,capabilities,ruleHash:resolution.ruleHash}});if(spent.spent<.25)return {needId:need.id,action:'growth-held-insufficient-budget',capabilities,resolution,selfOriginated:true};let candidate=null;let result=null;let validation=null;const before=this.unit.runtime.getRegisteredTools().length;try{candidate=await this.unit.factory.ensureTool(context.expression,context);if(!candidate)throw new Error('factory returned no candidate');result=await candidate.execute(context);validation=this.rules.validateCandidate({candidate,capabilities,resolution});const accepted=result?.success===true&&validation.pass===true;if(accepted){this.unit.runtime.registerTool(candidate);const after=this.unit.runtime.getRegisteredTools().length;const growth={type:'anatomical-growth',needId:need.id,toolId:candidate.toolId,capabilities,fromTools:before,toTools:after,accepted:true,resolution,validation,evidence:{type:'bounded-candidate-execution',success:true,ruleHash:resolution.ruleHash},at:Date.now()};this.growths.push(growth);this.needs.attempt(need.id,{kind:'tool-growth',candidateId:candidate.toolId,ok:true,result:{success:true,fromTools:before,toTools:after,ruleHash:resolution.ruleHash}});this.needs.satisfy(need.id,{evidence:{type:'tool-retained',toolId:candidate.toolId,ruleHash:resolution.ruleHash},result:growth});this.metabolism.relieveRepairPressure(.1,{reason:'retained five-dimensionally valid new capability'});this.unit.checkpoint?.();return {needId:need.id,action:'grew-and-retained-tool',toolId:candidate.toolId,capabilities,fromTools:before,toTools:after,resolution,validation,result:{success:true},selfOriginated:true};}throw new Error(String(result?.outputValues?.error||(!validation?.pass?'candidate failed five-dimensional validation':'candidate execution failed')));}catch(error){if(candidate)await this.unit.factory.rejectTool(candidate,String(error));const growth={type:'anatomical-growth',needId:need.id,toolId:candidate?.toolId||null,capabilities,fromTools:before,toTools:this.unit.runtime.getRegisteredTools().length,accepted:false,resolution,validation,error:String(error),at:Date.now()};this.growths.push(growth);this.needs.attempt(need.id,{kind:'tool-growth',candidateId:candidate?.toolId||null,ok:false,result:growth});return {needId:need.id,action:'tested-and-rejected-tool',toolId:candidate?.toolId||null,capabilities,resolution,validation,result:{success:false,error:String(error)},selfOriginated:true};}}
  async #useCapability(capability,need){const tool=this.unit.runtime.getRegisteredTools().find(t=>t.provides?.includes(capability));if(!tool)return null;const context=this.#growthContext(need,[capability]);const result=await tool.execute(context);this.unit.runtime.toolRegistry.recordOutcome(tool.toolId,result?.success===true);this.needs.attempt(need.id,{kind:'grown-tool-reuse',candidateId:tool.toolId,ok:result?.success===true,result});if(result?.success===true){this.metabolism.relieveRepairPressure(.06,{reason:`grown capability ${capability} executed successfully`});this.needs.satisfy(need.id,{evidence:{type:'grown-tool-reused',toolId:tool.toolId,capability},result:{success:true}});return {needId:need.id,action:'reused-grown-tool',toolId:tool.toolId,capability,result:{success:true},selfOriginated:true};}return {needId:need.id,action:'grown-tool-reuse-failed',toolId:tool.toolId,capability,result:{success:false,error:result?.outputValues?.error||null},selfOriginated:true};}
  #growthContext(need,capabilities){const input=this.lastCollective?.input||{};const dimension=Number(need.context?.dimension||input.canonicalAddress?.dimension||5);let canonicalAddress=input.canonicalAddress||null;if(!canonicalAddress){try{canonicalAddress=this.unit.resolveAddress(`autonomous growth ${capabilities.join(' ')}`).canonical;}catch{canonicalAddress=null;}}return {sessionId:`life-growth-${this.pulses}-${Date.now()}`,expression:{channelActivationId:`need:${need.id}`,inputPorts:[],outputPorts:[],capabilities,parameters:{pressure:need.pressure,repairPressure:this.metabolism.repairPressure},constraints:['bounded-growth','five-dimensional-rule-resolution-required']},inputValues:{intent:`autonomous growth for ${need.reason}`,intentRecord:{dimension},canonicalAddress,structure:'hexagram',sourceState:null,targetState:null,messages:[]},runtimeState:null};}
  #adaptableParent(){const selected=this.fabric.status().processes?.filter(p=>p.status==='selected'&&p.members?.length>1)||[];return selected.find(p=>p.members.every(m=>SAFE_REPLAY.has(m)))||null;}
  async #testCandidate(candidate){if(!this.lastCollective?.input)return {better:false,reason:'no safe replay input',score:0};if(!candidate.members.every(m=>SAFE_REPLAY.has(m)))return {better:false,reason:'side-effect boundary',score:0};const parent=this.fabric.inspect(candidate.parentId);if(!parent)return {better:false,reason:'missing parent',score:0};const input=this.lastCollective.input;const run=async route=>{const t=performance.now?.()??Date.now();const e=await this.coordinator.execute(route,input,{internalReplay:true});const ms=(performance.now?.()??Date.now())-t;return {ok:e.ok,contributors:e.contributors.length,durationMs:ms,eventId:e.id};};const a=await run(parent.members),b=await run(candidate.members);const equivalent=b.ok===a.ok&&b.contributors>=a.contributors;const better=equivalent&&b.durationMs<a.durationMs*.95;return {better,equivalent,parent:a,candidate:b,score:equivalent?(a.durationMs/(b.durationMs||.001)):0};}
  #safeInput(input){const x={};for(const k of ['intent','address','canonicalAddress','mode','gates','comparison','purpose'])if(k in input)x[k]=clone(input[k]);return x;}
  snapshot(){return {running:Boolean(this.timer),pulses:this.pulses,lastPulseAt:this.lastPulseAt,needs:this.needs.snapshot(),variations:this.variation.snapshot(),growths:this.growths.slice(-64).map(clone),toolCount:this.unit.runtime.getRegisteredTools().length,events:this.events.slice(-96).map(clone)};}
}
export default LivingLoop;
